{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "ae",
    "window": 3,
    "threshold_q": 0.995,
    "persistence": 3
  },
  "intent_understood_as": "defend_unknown_attacks",
  "reason": "Intent targets zero-day (never-seen) attacks. Only ae detects novel types like GTP-U. Default threshold (q=0.995) gives ~24 false alarms/hour, exceeding the 25 budget. Raising persistence to 3 cuts false alarms to ~7.7/hour, well within the 25/hour limit, while still detecting novel attacks."
}
